using System;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Threading;
class ReopenPageTests {static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Call(object o,string n,params object[] a){o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}[STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();var frame=new DispatcherFrame();var pump=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(120)};pump.Tick+=(o,e)=>{pump.Stop();frame.Continue=false;};pump.Start();Dispatcher.PushFrame(frame);((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();foreach(string page in new[]{"健康","提醒","进程监控","Codex状态","健康"}){Call(pet,"OpenTerminal");var terminal=(TerminalWindow)Get(pet,"terminal");terminal.ShowPage(page);terminal.Close();Call(pet,"OpenTerminal");terminal=(TerminalWindow)Get(pet,"terminal");terminal.ShowPage(page);terminal.Close();Console.WriteLine("PASS reopen embedded page "+page);}return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{if(pet!=null)pet.Close();app.Shutdown();}}}
